/**  Another client owns the credential; Quota only reads it. */
"external_client";

/**  One credit grant: how much it was, how much is left, and when it lapses. */
export type CreditGrant = {
	/**  What the grant was for. */
	kind: CreditKind,
	/**  How much it granted, in minor units. */
	amount_minor: number | null,
	/**  How much of it is left, in minor units. */
	remaining_minor: number | null,
	/**  When it expires. */
	expires_at: string,
};

/**  What a credit grant was for. */
export type CreditKind = 
/**  Credit the provider gives for free. */
"free" | 
/**  Credit the person bought. */
"purchased" | 
/**  Any other grant, such as a promotion. */
"other";

/**  An ISO 4217-style currency code. */
export type CurrencyCode = string;

/**  What the account spent in its current billing cycle. */
export type CycleSpend = {
	/**  The cycle, as the provider names it, for example `October 2026`. */
	label: string,
	/**  Spent in it, in minor units. */
	spent_minor: number | null,
};

/**  Decimal places a provider used when it reported a number. */
export type DecimalPrecision = number;

/**  A version of a window or account definition, as reported by the provider. */
export type DefinitionVersion = number;

/**  How strongly the provider enforces this limit. */
export type Enforcement = 
/**  New work is refused. */
"hard" | 
/**  The provider warns but continues. */
"soft" | 
/**  The value is only reported. */
"informational" | 
/**  The source did not say. */
"unknown";

/**  A provider-reported plan or entitlement context. */
export type EntitlementId = string;

/**  A notification source plus its verification interval. */
export type EventAssistedPolicy = {
	/**  The provider's floor, also used for the verification read. */
	minimum_seconds: number,
	/**  How often a read verifies a push that may not have refreshed server data. */
	verification_seconds: number,
};

/**  How the last read attempt went. This is not a quota severity. */
export type FetchState = 
/**  Nothing is due yet. */
"idle" | 
/**  A read is in flight. */
"fetching" | 
/**  Waiting out a provider backoff. */
"backoff" | 
/**  The host reports no network. */
"offline" | 
/**  The last attempt failed. */
"error";

/**  What fitting the mini widget to its content decided. */
export type FitWidget = {
	/**
	 *  The fitted content height in logical pixels; below the asked height
	 *  only when neither side had room and the drawer is capped.
	 */
	height: number | null,
	/**  The side the window grew or shrank on. */
	direction: WidgetGrowth,
	/**  The free room above the window in logical pixels. */
	room_above: number | null,
	/**  The free room below the window in logical pixels. */
	room_below: number | null,
};

/**  Separate validated intervals for each display and power mode. */
export type FixedIntervalPolicy = {
	/**  Interval while an overview is visible and the adapter permits it. */
	visible_seconds: number,
	/**  Interval while only the tray is running. */
	background_seconds: number,
	/**  Interval during battery saver or prolonged idle. */
	battery_saver_seconds: number,
	/**  The provider's floor. No other interval may be shorter. */
	minimum_seconds: number,
};

/**  One group as the renderer sees it: its members and the account total. */
export type GroupSnapshot = {
	/**  The group's immutable identity. */
	id: AccountGroupId,
	/**  The provider every member belongs to. */
	provider_id: ProviderId,
	/**  The person's name for the provider account. */
	name: string,
	/**  The members, in the snapshot's account order. */
	account_ids: AccountId[],
	/**  The account-wide balance, from the member that read it last. */
	balance: BalanceSummary | null,
	/**  What every member key spent together, per period any member reports. */
	key_spend: PeriodSpend | null,
};

/**  How a remaining allowance is drawn. */
export type IndicatorStyle = 
/**  A small draining ring. */
"ring" | 
/**  A horizontal bar. The same values, a different indicator. */
"bar";

/**  What happens at login. */
export type LaunchBehavior = 
/**  Start in the tray without opening a window. */
"quiet_in_tray" | 
/**  Restore the last chosen mode. */
"restore_last_mode";

/**
 *  A normalised reading of one allowance.
 * 
 *  The variants are mutually exclusive on purpose: exhausted, not entitled,
 *  unlimited, and unknown are different facts and must never collapse into a
 *  fabricated zero.
 */
export type Measurement = 
/**  A reported or derived percentage. */
{ kind: "percentage"; value: PercentageMeasurement } | 
/**  A count in a provider unit. */
{ kind: "quantity"; value: QuantityMeasurement } | 
/**  An amount of money. */
{ kind: "money"; value: MoneyMeasurement } | 
/**  The capability has no ceiling. */
{ kind: "unlimited" } | 
/**  The plan does not include this capability at all. */
{ kind: "not_entitled" } | 
/**  No usable number is available. */
{ kind: "unavailable"; value: UnavailableReason };

/**  What the number represents in the plan. */
export type MetricRole = 
/**
 *  The allowance included in the subscription. The only finite role eligible
 *  for the least-remaining ranking.
 */
"included_allowance" | 
/**  A ceiling on extra spend. Not included quota. */
"extra_spend_cap" | 
/**  An informational balance. Not included quota. */
"credit_balance" | 
/**
 *  A prepaid balance measured from its last top-up. Not included quota,
 *  but it runs out the same way, so it ranks and alerts like one.
 */
"prepaid_balance";

/**
 *  A monetary allowance, such as a monthly extra-spend cap.
 * 
 *  Amounts are integer minor units (for example cents) with the scale recorded
 *  alongside, so no rounding is introduced by the application.
 */
export type MoneyMeasurement = {
	/**  The currency the provider reported. */
	currency: CurrencyCode,
	/**  Number of decimal places in one major unit, for example 2 for cents. */
	scale: number,
	/**  Amount consumed, when the provider reported it. */
	used_minor_units: number | null,
	/**  Amount still available, when the provider reported it. */
	remaining_minor_units: number | null,
	/**  The cap itself, when the provider reported one. */
	limit_minor_units: number | null,
};

/**  Whether the supervisor is scheduling reads. */
export type MonitoringState = 
/**  Reads are scheduled. */
{ kind: "running" } | 
/**  The user paused monitoring. */
{ kind: "paused" } | 
/**  The supervisor stopped after a failure and is not scheduling. */
{ kind: "recovery_required"; reason: string };

/**  Whether the supervisor is scheduling reads. */
export type MonitoringStateChanged = MonitoringStateChangedPayload;

/**  Whether the supervisor is scheduling reads. */
export type MonitoringStateChangedPayload = {
	/**  Which application instance published this. */
	app_instance_id: AppInstanceId,
	/**  Monotonic within one instance. */
	monitoring_revision: number,
	/**  The confirmed state. */
	monitoring_state: MonitoringState,
};

/**
 *  Which of the three allowance alerts are switched on.
 * 
 *  Each alert is its own choice: the approved design offers 20%, 10%, and 0% as
 *  three separate selections, so one shared percentage cannot stand in for
 *  them, and a deselected alert is never written as a null percentage.
 */
export type NotificationAlerts = {
	/**  Notify when an allowance reaches the low threshold. */
	low: boolean,
	/**  Notify when an allowance reaches the critical threshold. */
	critical: boolean,
	/**  Notify when an allowance is exhausted. */
	exhausted: boolean,
};

/**  What the user wants to be told. */
export type NotificationPolicy = {
	/**  Whether notifications are enabled at all. */
	enabled: boolean,
	/**  The downward thresholds. */
	thresholds: NotificationThresholds,
	/**  When notifications are suppressed. */
	quiet_hours: QuietHours,
	/**  Whether recovery notifications are sent separately. */
	recovery_enabled: boolean,
};

/**  Default thresholds, expressed as remaining percentage. */
export type NotificationThresholds = {
	/**  Remaining percentage at which the allowance is called low. */
	low_percent: number | null,
	/**  Remaining percentage at which the allowance is called critical. */
	critical_percent: number | null,
	/**  How far past a threshold a reading must recover before it re-arms. */
	hysteresis_percent: number | null,
	/**  Which of the three alerts are switched on. */
	alerts?: NotificationAlerts,
};

/**  One account's position in the canonical order. */
export type OrderEntry = {
	/**  The account. */
	account_id: AccountId,
	/**  Its section. */
	section: OrderSection,
	/**  Its rank, when ranked. */
	order: AccountOrder,
	/**  Stable tie-break order. */
	connection_ordinal: number,
};

/**  Which presentation section an account belongs to. */
export type OrderSection = 
/**  Accounts that need a connection, reading, or boundary check. */
"needs_checking" | 
/**  Accounts with a comparable remaining percentage. */
"ranked" | 
/**  Accounts the user switched off. */
"monitoring_off";

/**  Where the overview lives. */
export type OverviewMode = 
/**  A freely movable window that stays open. */
"floating" | 
/**  A window anchored beside the tray. */
"tray";

/**  Confirmed native overview window state, or a typed native failure. */
export type OverviewWindowState = 
/**  The native state was confirmed. */
{ kind: "confirmed"; value: {
	/**  The window mode in effect. */
	mode: OverviewMode,
	/**  Whether the window floats above other applications. */
	always_on_top: boolean,
	/**  Whether the window is currently shown. */
	visible: boolean,
	/**  The geometry revision, incremented on every confirmed change. */
	geometry_revision: number,
} } | 
/**  The platform refused or failed the operation. The previous state stands. */
{ kind: "failed"; value: {
	/**  The typed failure. */
	error: CommandError,
} };

/**  Confirmed native overview window state, or a typed native failure. */
export type OverviewWindowStateChanged = OverviewWindowStateChangedPayload;

/**  A change to the native overview window. */
export type OverviewWindowStateChangedPayload = {
	/**  Which application instance published this. */
	app_instance_id: AppInstanceId,
	/**  The confirmed state or failure. */
	state: OverviewWindowState,
};

/**
 *  A credential the person pasted, such as an API key.
 * 
 *  It never prints its value, so a logged request cannot leak it.
 */
export type PastedCredential = string;

/**
 *  A finite percentage of an allowance.
 * 
 *  The stored value is never rounded, clamped, or re-polaritised. Display
 *  formatting and the donut arc are derived from it, so overspend above 100%
 *  used survives the round trip.
 */
export type Percent = number | null;

/**  A provider-reported percentage of an allowance, with its original polarity. */
export type PercentageMeasurement = {
	/**  The provider's own used percentage, kept verbatim. */
	used_percent: Percent,
	/**  `100 - used_percent`, kept unrounded. */
	remaining_percent: Percent,
	/**  Decimal places the provider reported. */
	precision: DecimalPrecision,
};

/**  What a key spent today, this week and this month, in minor units. */
export type PeriodSpend = {
	/**  Spent in the current UTC day. */
	today_minor: number | null,
	/**  Spent in the current UTC week. */
	week_minor: number | null,
	/**  Spent in the current UTC month. */
	month_minor: number | null,
};

/**  Whether durable storage is usable. */
export type PersistenceStatus = 
/**  Every durable owner is available. */
{ kind: "available" } | 
/**  One owner is degraded; readings continue without durable history. */
{ kind: "degraded"; detail: string } | 
/**  A mandatory owner could not be opened, so no polling starts. */
{ kind: "recovery_required"; detail: string };

/**  Durable storage availability. */
export type PersistenceStatusChanged = PersistenceStatusChangedPayload;

/**  Durable storage availability, with no file contents or credential references. */
export type PersistenceStatusChangedPayload = {
	/**  Which application instance published this. */
	app_instance_id: AppInstanceId,
	/**  The current status. */
	status: PersistenceStatus,
};

/**  How often an adapter wants to be read. */
export type PollingStrategy = 
/**  Separate validated intervals per visibility and power mode. */
{ kind: "fixed_interval"; settings: FixedIntervalPolicy } | 
/**  Frequency adjusted from approved change signals within bounds. */
{ kind: "adaptive"; settings: AdaptivePolicy } | 
/**  Provider notifications plus periodic verification. */
{ kind: "event_assisted"; settings: EventAssistedPolicy } | 
/**  Base polling plus a bounded verification near a reported boundary. */
{ kind: "boundary_aware"; settings: BoundaryAwarePolicy };

/**  The confirmed preference aggregate. */
export type Preferences = {
	/**  The wire schema version. */
	schema_version: number,
	/**  Monotonic within one installation. */
	revision: number,
	/**  The colour scheme. */
	theme: Theme,
	/**  The allowance indicator. */
	indicator_style: IndicatorStyle,
	/**  Where the overview lives. */
	overview_mode: OverviewMode,
	/**  Whether the overview floats above other applications. Off by default. */
	always_on_top: boolean,
	/**  What happens at login. */
	launch_behavior: LaunchBehavior,
	/**  Whether animations are suppressed. */
	reduce_motion: boolean,
	/**  Which view presents the app: the full window or the mini widget. */
	view: AppView,
	/**
	 *  Where the widget was last left. The host saves it when the widget moves;
	 *  the renderer carries it through a save unchanged.
	 */
	widget_position: WidgetPosition | null,
	/**  Notification behaviour. */
	notifications: NotificationPolicy,
	/**  Retention and export behaviour. */
	privacy: PrivacyPolicy,
	/**  The effective per-provider polling policy. */
	polling: ProviderPollingPolicy[],
};

/**  Emitted after a preference save succeeds, never before. */
export type PreferencesChanged = PreferencesChangedPayload;

/**  Emitted after a preference save succeeds, never before. */
export type PreferencesChangedPayload = {
	/**  Which application instance published this. */
	app_instance_id: AppInstanceId,
	/**  The confirmed preference revision. */
	preference_revision: number,
	/**  The confirmed preferences. */
	preferences: Preferences,
};

/**  How account identities appear in the overview. */
export type PrivacyAliasMode = 
/**  Show the verified nickname and workspace. */
"off" | 
/**  Replace each account with a stable, distinguishable alias. */
"stable_aliases";

/**  How much local detail is retained and exported. */
export type PrivacyPolicy = {
	/**  Whether account identities are replaced by stable aliases. */
	alias_mode: PrivacyAliasMode,
	/**  Whether normalized local history is retained. */
	retain_history: boolean,
	/**  Whether diagnostic export includes account labels. */
	export_identities: boolean,
};

/**  What an adapter declares it can do, before any account exists. */
export type ProviderCapabilities = {
	/**  The provider this capability set belongs to. */
	provider_id: ProviderId,
	/**  How many independent accounts can be monitored at once. */
	cardinality: AccountCardinality,
	/**  Whether Quota can obtain its own authorization. */
	supports_app_owned_authorization: boolean,
	/**  Whether Quota can read an externally owned client profile. */
	supports_external_profile: boolean,
	/**  Whether the provider reports a monthly allowance. */
	reports_monthly_window: boolean,
	/**  The shortest interval this adapter permits between reads. */
	minimum_interval_seconds: number,
};

/**
 *  The providers this build knows about.
 * 
 *  The vocabulary is closed on purpose: an unknown provider name in imported or
 *  newer persisted data produces an explicit unsupported state, never an
 *  arbitrary adapter lookup.
 */
export type ProviderId = 
/**  `OpenAI` Codex, through its documented `app-server` rate-limit interface. */
"codex" | 
/**  Claude subscription usage. */
"claude" | 
/**  `OpenCode` `Go`, the provider reached through a local `OpenCode` Go agent. */
"open_code_go" | 
/**  `OpenRouter` credits and API key spend limits, signed in with an API key. */
"openrouter" | 
/**  The Z.ai GLM Coding Plan, signed in with an API key. */
"zai" | 
/**  The `MiniMax` Coding (token) Plan, signed in with an API key. */
"minimax" | 
/**  Kimi for Coding, signed in with an API key or the Kimi CLI's sign-in. */
"kimi" | 
/**  `SuperGrok`, signed in through the browser or the Grok CLI. */
"grok" | 
/**  Meta's Muse Code, signed in through the browser or the Muse CLI. */
"muse_code" | 
/**  Cursor, read with the sign-in the Cursor app keeps. */
"cursor" | 
/**  Ollama Cloud, read with Ollama's own sign-in or an API key. */
"ollama_cloud" | 
/**  `TypeSafe` credits, read with a console session Quota signs in to itself. */
"typesafe" | 
/**
 *  A deterministic local provider used only by tests and developer runs.
 * 
 *  The adapter for this identifier is compiled only under the non-default
 *  `test-fixtures` Cargo feature, so a release build contains no code that
 *  can serve it.
 */
"fixture";

/**  A validated policy attached to one provider. */
export type ProviderPollingPolicy = {
	/**  The provider this policy belongs to. */
	provider_id: ProviderId,
	/**  The strategy the adapter declared. */
	strategy: PollingStrategy,
	/**  The remote request deadline. */
	request_timeout_seconds: number,
	/**  The helper startup and read deadline, when a helper is used. */
	helper_timeout_seconds: number,
	/**  Backoff steps for transient failures. */
	backoff_minutes: number[],
	/**  The largest number of simultaneous remote reads. */
	max_concurrent_remote_reads: number,
	/**  The version of this policy, so a stale persisted policy is detectable. */
	version: number,
};

/**  A provider-verified principal, such as the signed-in user. */
export type ProviderPrincipalId = string;

/**  A counted allowance in a provider unit. */
export type QuantityMeasurement = {
	/**  The unit the count is expressed in. */
	unit: QuotaUnit,
	/**  Decimal places the provider reported. */
	precision: DecimalPrecision,
	/**  Amount consumed, when reported. */
	used: number | null,
	/**  Amount still available, when reported. */
	remaining: number | null,
	/**  The allowance itself, when reported. */
	limit: number | null,
};

/**  When notifications may be shown. */
export type QuietHours = 
/**  Notifications are always permitted. */
{ kind: "never" } | 
/**  Notifications are suppressed inside a daily UTC window. */
{ kind: "daily_utc"; window: {
	/**  Minutes from midnight when quiet hours start. */
	from_minute: number,
	/**  Minutes from midnight when quiet hours end. */
	to_minute: number,
} };

/**
 *  The period a window covers, as a projection category.
 * 
 *  The three common UI columns are derived from this; they are not a fixed
 *  three-field schema.
 */
export type QuotaCategory = 
/**  A short rolling session allowance, often five hours. */
"session" | 
/**  A weekly allowance. */
"weekly" | 
/**  A monthly allowance. */
"monthly" | 
/**  A daily allowance. */
"daily" | 
/**  A provider-defined period. */
"custom";

/**
 *  A structured problem found while decoding or normalising a provider reading.
 * 
 *  The variant is the machine-readable contract. Any display text is a
 *  supplement and never a control-flow signal.
 */
export type QuotaIssue = 
/**  A reported number was NaN or infinite. */
{ code: "non_finite_value"; context: {
	/**  The field that carried the unusable number. */
	field: string,
} } | 
/**  A percentage was computed from a zero or negative denominator. */
{ code: "non_positive_denominator" } | 
/**  Reported remaining and limit values contradict each other. */
{ code: "contradictory_counts"; context: {
	/**  The reported remaining value. */
	remaining: number | null,
	/**  The reported limit value. */
	limit: number | null,
} } | 
/**  Usage was reported as negative. */
{ code: "negative_usage"; context: {
	/**  The negative value the provider reported. */
	value: number | null,
} } | 
/**  A persisted or remote schema version this build cannot interpret. */
{ code: "unsupported_schema_version"; context: {
	/**  The version the provider or file declared. */
	version: number,
} } | 
/**  A resource scope did not match the scope the window is defined for. */
{ code: "scope_mismatch"; context: {
	/**  The scope the window expects. */
	expected: string,
	/**  The scope the provider actually reported. */
	actual: string,
} };

/**  A provider-confirmed shared allowance owner, or an opaque isolated pool. */
export type QuotaPoolId = string;

/**
 *  A metered resource plus the label shown beside it.
 * 
 *  The scope must survive every mapping from provider payload to renderer, so it
 *  travels with the window rather than being recovered from a label.
 */
export type QuotaScope = {
	resource: ResourceId,
	label: string,
};

/**  The unit a counted allowance is expressed in. */
export type QuotaUnit = 
/**  A count of billable requests. */
{ kind: "requests" } | 
/**  A count of model tokens. */
{ kind: "tokens" } | 
/**  A count of conversation messages. */
{ kind: "messages" } | 
/**  A count of prepaid credits. */
{ kind: "credits" } | 
/**  A provider-defined unit, carried verbatim as text. */
{ kind: "custom"; symbol: UnitSymbol };

/**  One allowance, for one account, over one period. */
export type QuotaWindow = {
	/**  Stable identity of this pool, scope, metric and period definition. */
	id: QuotaWindowId,
	/**  The provider's own bucket identifier, when it reported one. */
	provider_bucket_id: string | null,
	/**  The allowance owner. Several accounts may share one pool. */
	pool_id: QuotaPoolId,
	/**  The metered resource. */
	scope: QuotaScope,
	/**  The period category this window projects into. */
	category: QuotaCategory,
	/**  What the period actually means. */
	semantics: WindowSemantics,
	/**  The reported duration, when the source gave one. Never decides semantics. */
	duration: string | null,
	/**  Whether this is included quota, an extra-spend cap, or a balance. */
	metric_role: MetricRole,
	/**  How strongly the provider enforces the limit. */
	enforcement: Enforcement,
	/**  The normalised reading. */
	measurement: Measurement,
	/**  When the current period started, when known. */
	period_started_at: string | null,
	/**  When the allowance changes, when known. */
	boundary: Boundary | null,
	/**  When the provider says it observed the value. */
	observed_at: string | null,
	/**  When this process received it. */
	received_at: string,
	/**  After this instant the reading is stale, when the source defines one. */
	valid_until: string | null,
	/**  Where the reading came from. */
	source: SourceKind,
	/**  Whether every applicable field arrived. */
	completeness: Completeness,
	/**  The provider's version of this window definition. */
	definition_version: DefinitionVersion,
	/**  Structured validation findings. */
	issues: QuotaIssue[],
};

/**  A stable pool, scope, metric and period definition. */
export type QuotaWindowId = string;

/**  A comparable rank plus the window that produced it. */
export type RankedOrder = {
	/**  The lowest known included remaining percentage, unrounded. */
	remaining_percent: Percent,
	/**  The window that controlled the value. */
	controlling_window_id: QuotaWindowId,
	/**  That window's scope, so the UI can explain the position. */
	scope_label: string,
	/**  The version of the rule that produced this result. */
	rule_version: number,
};

/**  Why a refresh was requested. */
export type RefreshReason = 
/**  The user asked for a refresh. */
"user_requested" | 
/**  The supervisor scheduled an ordinary interval read. */
"scheduled" | 
/**  A reported boundary passed and needs verification. */
"boundary_verification" | 
/**  The overview was opened and the cached snapshot is older than policy. */
"overview_opened" | 
/**  The host reported that it resumed from sleep. */
"resumed";

/**  One compiled adapter and what it declares it can do. */
export type RegisteredProvider = {
	/**  The provider identifier. */
	provider_id: ProviderId,
	/**  What the adapter declares. */
	capabilities: ProviderCapabilities,
	/**  Whether the adapter is compiled into this build at all. */
	compiled_in_this_build: boolean,
};

/**  A metered resource such as a model or product surface. */
export type ResourceId = string;

/**  The spending pace, and how long the balance lasts at it. */
export type Runway = {
	/**  Spent per day, on average, over the pace period. */
	spend_per_day_minor: number | null,
	/**  Whole days the balance lasts at that pace. */
	days_left: number,
};

/**  Arguments for enabling or disabling one account. */
export type SetAccountEnabledRequest = {
	/**  The account to change. */
	account_ref: AccountRef,
	/**  Whether it should be monitored. */
	enabled: boolean,
	/**  The preference revision the caller believes is current. */
	expected_revision: number,
};

/**  The settings surface requested by an overview action. */
export type SettingsDestination = 
/**  General window and monitoring settings. */
"general" | 
/**  Connected account management. */
"accounts" | 
/**  Provider connection wizard. */
"connect";

/**  The snapshot plus the revision the renderer should reconcile against. */
export type SnapshotResponse = {
	/**  The complete, sanitized snapshot. */
	snapshot: AppSnapshot,
};

/**  The primary quota and account update channel. */
export type SnapshotUpdated = SnapshotUpdatedPayload;

/**  The primary quota and account update channel. */
export type SnapshotUpdatedPayload = {
	/**  Which application instance published this. */
	app_instance_id: AppInstanceId,
	/**  The snapshot revision, monotonic within the instance. */
	revision: number,
	/**  The wire schema version of `snapshot`. */
	schema_version: number,
	/**  The complete, sanitized snapshot. */
	snapshot: AppSnapshot,
};

/**  Where a reading came from. */
export type SourceKind = 
/**  A documented provider API. */
"documented_api" | 
/**  A documented command-line protocol. */
"documented_cli_protocol" | 
/**  An observed provider web endpoint, not a public contract. */
"observed_web_endpoint" | 
/**  A locally captured response. */
"local_capture" | 
/**  Entered by the user. */
"manual";

/**  The colour scheme. */
export type Theme = 
/**  Follow the operating system. */
"system" | 
/**  Always light. */
"light" | 
/**  Always dark. */
"dark";

/**  One top-up, as Quota saw it. */
export type TopUp = {
	/**  The reading that first showed it. */
	detected_at: string,
	/**  How much was loaded. */
	amount_minor: number | null,
	/**  The balance right after it: the balance before, plus the amount. */
	balance_after_minor: number | null,
};

/**  Why an allowance has no usable number. */
export type UnavailableReason = 
/**  The provider was expected to report this window and did not. */
"not_reported" | 
/**  The source cannot express this window at all. */
"unsupported" | 
/**  The provider answered, but the payload could not be interpreted. */
"invalid_response" | 
/**  The window does not apply to this account. */
"not_applicable";

/**  A provider-defined unit that the closed vocabulary does not cover. */
export type UnitSymbol = string;

/**  An explicit absence of rank. */
export type UnrankedOrder = {
	/**  Why there is no comparable value. */
	reason: UnrankedReason,
	/**  The version of the rule that produced this result. */
	rule_version: number,
};

/**  Why an account has no comparable numeric rank. */
export type UnrankedReason = 
/**  The reading is past its freshness deadline. */
"stale" | 
/**  An applicable window was expected and is missing. */
"incomplete" | 
/**  The account needs a new authorization. */
"reconnect_required" | 
/**  A reported boundary has passed and no fresh reading has arrived. */
"reset_pending" | 
/**  The account only reports native units with no denominator. */
"native_units_only" | 
/**  Every applicable window is unlimited. */
"unlimited_only" | 
/**  The account is not monitored. */
"disabled" | 
/**  Monitoring is paused application-wide. */
"monitoring_paused" | 
/**  No included allowance applies to this account. */
"no_included_allowance";

/**  What the update pop-up is showing. */
export type UpdatePrompt = 
/**  A newer version is published and the person is asked about it. */
{ kind: "offer"; context: {
	/**  The version on offer, such as `0.2.0`. */
	version: string,
	/**  The version running now. */
	current: string,
} } | 
/**  The person said yes; the update is downloading and installing. */
{ kind: "installing"; context: {
	/**  The version being installed. */
	version: string,
} } | 
/**  The update was accepted and could not be installed. */
{ kind: "failed" };

/**  The update pop-up changed what it shows. */
export type UpdatePromptChanged = UpdatePromptChangedPayload;

/**  The pop-up changed what it shows. */
export type UpdatePromptChangedPayload = {
	/**  What the pop-up shows now. */
	prompt: UpdatePrompt,
};

/**  What the person pressed in the update pop-up. */
export type UpdateResponse = 
/**  OK: install the offered update now. */
"install" | 
/**  Cancel, or closing the pop-up, on an offer. */
"decline" | 
/**  Close, on the message that the install failed. */
"dismiss";

/**
 *  A verified identity held for the person's decision, and not yet saved.
 *  Nothing about this type names a stored account, so a candidate that is never
 *  confirmed leaves no account behind. It carries no secret material.
 */
export type VerifiedCandidate = {
	/**  The adapter that reported this identity. */
	provider_id: ProviderId,
	/**  The nickname the person asked for. Presentation only. */
	nickname: string,
	/**  The provider-verified principal, workspace, plan, and source. */
	identity: VerifiedIdentity,
	/**  The quota reading this attempt verified. */
	windows: QuotaWindow[],
};

/**  A provider-verified identity, shown for confirmation. */
export type VerifiedIdentity = {
	/**  Human-readable principal label, such as a masked address. */
	principal_label: string,
	/**  Workspace or team label. */
	workspace_label: string | null,
	/**  Plan label, when the provider reports one. */
	plan_label: string | null,
	/**  Where the identity was verified. */
	source: SourceKind,
};

/**  Which way the mini widget window grows for its details drawer. */
export type WidgetGrowth = 
/**  The top edge stays and the bottom moves down. */
"down" | 
/**  The bottom edge stays and the top moves up. */
"up";

/**
 *  Where the mini widget was last left: its top-left corner in physical
 *  screen pixels, which is what the system reports and accepts.
 */
export type WidgetPosition = {
	/**  Pixels from the left of the virtual desktop. */
	x: number,
	/**  Pixels from the top of the virtual desktop. */
	y: number,
};

/**  A confirmed overview mode change, or the state that was actually reached. */
export type WindowModeChange = 
/**  The window is now in this mode. */
{ kind: "applied"; value: OverviewMode } | 
/**  The platform refused, and the previous mode is still in effect. */
{ kind: "refused"; value: {
	/**  The sanitized reason the platform gave. */
	reason: string,
	/**  The mode still in effect. */
	current: OverviewMode,
} };

/**  What a duration actually means. A duration alone never decides this. */
export type WindowSemantics = 
/**  A period anchored to a start time. */
"anchored_period" | 
/**  A genuinely rolling window. */
"rolling_period" | 
/**  A calendar billing cycle. */
"calendar_cycle" | 
/**  The source did not say. */
"unknown";

/**  A provider workspace or team within a principal. */
export type WorkspaceId = string;

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

